sketches.source:
setcpm(112/2)

// One cycle is a bar of 2/4. The corps rolls off, marches by in G, plays a trio in C and halts
song("roll@4 march@16 trio@16 march'@16 roll'@4 trio@16 march''@16 halt@4", "once")
tempomap("0:56 88:56 92:40")

const tune = note("<[g5 a5 b5 g5] [a5 b5 [c6 b5] a5] [b5 c6 d6 b5] [a5 [b5 a5] g5 d5] [g5 a5 b5 g5] [a5 b5 [c6 b5] a5] [b5 [a5 g5] a5 f#5] [g5@2 g5 ~]>")
const trio = note("<[e5 g5 c6 g5] [a5 g5 e5 c5] [d5 e5 f5 d5] [g5@2 g5 ~] [e5 g5 c6 g5] [a5 g5 f5 e5] [d5 [e5 d5] c5 b4] [c5@2 c5 ~]>")
const halt = note("<[d5 g5 b5 g5] [d6@2 ~@2] [b5 g5 d5 b4] [g5@3 ~]>")

// The fife: the march, the trio and the final call to halt
fife: stack(tune.sections("march"), trio.sections("trio"), halt.sections("halt"))
  .s("sine").timbre("hollow").vib(6).vibdepth(.06)
  .attack(.01).decay(.1).sustain(.6).release(.05)
  .space("outdoor").room(.3).gain(.28)

// A second fife joins an octave below on the repeats of the march
fife2: tune.add(-12).sections("march' march''")
  .s("sine").timbre("hollow").vib(6).vibdepth(.06)
  .attack(.01).decay(.1).sustain(.6).release(.05)
  .space("outdoor").room(.3).pan(.6).gain(.2)

// The drummers roll off, rising out of nothing
rolloff: s("sd*8").gain(env(".05 .45", "section")).hpf(400)
  .space("outdoor").room(.3).sections("roll")

// Snare rudiments: open strokes and buzzing doubles, with a fill at the end of every strain
snare: s("[sd sd] [sd sd sd sd] [sd sd] [sd sd sd sd]").gain(".45 .25 .4 .25")
  .hpf(400).space("outdoor").room(.3).exceptSections("roll halt")
  .atEnd(1, x => x.ply(2))

// The bass drum on the beat, and boots on the road that come close and pass by
bassdrum: s("lt ~ lt ~").speed(.7).lpf(500).gain(.5).exceptSections("roll")
steps: s("step ~ step ~").distance(bysec("roll:6 roll':6 halt:6 *:3")).gain(.18)

setcpm(100/4)

// Casting off, the tune and the locks twice, the tune once more up the octave, and mooring at dusk
song("cast@4 (tune@8 locks@8)*2 tune'@8 moor@4", "once")
tempomap("0:25 44:25 48:18")

const ripple = n("0 2 4 2 6 4 2 4")

// A hammered dulcimer rippling: D, D, G, A for the tune, D, C, G, D through the locks
dulcimer: stack(
  ripple.add("<0 0 3 4>").sections("cast tune"),
  ripple.add("<0 6 3 0>").sections("locks"),
  n("[0,4,7]").sections("moor")
).scale("D:mixolydian").transpose(12)
  .s("sine").fm(2.5).fmh(3).decay(.4).sustain(0).release(.5)
  .pan(.35).room(.4).gain(.22)

// The fiddle plays the tune and the second strain
fiddle: stack(
  note("<[a4@2 b4 c5 d5@2 c5 a4] [g4@3 a4 b4@2 g4 e4] [d4 e4 g4 a4 b4@2 a4 g4] [a4 g4 e4 c5 a4@4]>").sections("tune"),
  note("<[d5@2 c5 a4 g4@2 a4 b4] [c5@2 a4 g4 e4@4] [d4 e4 g4 a4 b4@2 a4 g4] [a4 g4 e4 f#4 d4@4]>").sections("locks")
).variant(x => x.add(12))
  .s("sawtooth").timbre("reed").lpf(2800).vib(6).vibdepth(.12)
  .attack(.03).sustain(.6).release(.15).pan(.65).room(.4).gain(.24)

// A boot stomping on the deck, and a jug for the bass
stomp: s("bd ~ bd ~").lpf(400).gain(.4).exceptSections("cast moor")
jug: stack(
  note("<[d2 ~ a1 ~] [d2 ~ a1 ~] [g1 ~ d2 ~] [a1 ~ e2 ~]>").sections("tune"),
  note("<[d2 ~ a1 ~] [c2 ~ g1 ~] [g1 ~ d2 ~] [d2 ~ a1 ~]>").sections("locks")
).s("sine").vowel("o").shape(.1).decay(.25).sustain(.2).gain(.4)

// Water against the hull
water: s("stream").slow(4).distance(3).gain(.15)

setcpm(80/4)

// The pitch pipe, verse and chorus twice, and a tag
song("pitch@1 (verse@8 chorus@8)*2 tag@4", "once")
tempomap("0:20 33:20 37:13")

// The pitch pipe gives the note
pipe: note("bb4").sections("pitch")
  .s("sine").vib(4).vibdepth(.03).attack(.05).release(.3).gain(.15)

// The lead sings the tune: Bb, G7, C7, F7, Bb, C7, F7, Bb in the verse; Eb, Bb, C7, F7, Bb, G7, C7-F7, Bb in the chorus
lead: stack(
  note("<[d4@2 c4 bb3 d4@2 f4@2] [d4@4 b3@4] [c4@2 d4 e4 g4@2 e4@2] [eb4@4 c4@4] [d4@2 f4@2 bb4@2 a4 g4] [f4@4 e4@4] [eb4@2 d4@2 c4@2 a3@2] [bb3@8]>")
    .syl("<[la@2 li la lo@2 ma@2] [ho@4 nu@4] [wa@2 la ro mi@2 nu@2] [so@4 mu@4] [la@2 di@2 lo@2 ma ri] [mo@4 nu@4] [ho@2 na@2 so@2 wa@2] [ho@8]>").sections("verse"),
  note("<[g4@3 f4 eb4@2 g4@2] [f4@4 d4@4] [e4@2 g4@2 c4@2 e4@2] [eb4@4 f4@4] [d4@2 f4@2 bb4@2 a4 g4] [g4@4 f4@4] [e4@2 g4@2 f4@2 eb4@2] [d4@8]>")
    .syl("<[la@3 di do@2 ma@2] [ho@4 nu@4] [wa@2 li@2 ro@2 mi@2] [so@4 nu@4] [la@2 di@2 lo@2 ma ri] [mo@4 nu@4] [ho@2 na@2 so@2 wa@2] [ho@8]>").sections("chorus"),
  note("[bb3 c4 d4@6]").slow(4).syl("[ho ma ho@6]").slow(4).sections("tag")
).s("voice").mono(1).vglide(.12).attack(.08).release(.4).room(.3).gain(.3)

// Tenor, baritone and bass ring the chords around it
harmony: stack(
  note("<[bb2,f3,f4] [g2,f3,d4] [c3,g3,bb3] [f2,c3,a3] [bb2,f3,d4] [c3,g3,bb3] [f2,a3,f4] [bb2,f3,d4,f4]>").sections("verse"),
  note("<[eb3,bb3,bb4] [bb2,f3,bb4] [c3,bb3,g4] [f2,a3,a4] [bb2,f3,f4] [g2,f3,b4] [c3,bb3,a4] [bb2,f3,f4]>").sections("chorus"),
  note("[[eb2,g3,bb3] [e2,g3,bb3] [f2,a3,eb4]@2 [bb2,f3,bb3,f4]@4]").slow(4).sections("tag")
).s("ooh").attack(.2).release(.6).room(.3).gain(.22)

// Footsteps on the boardwalk
steps: s("step ~ ~ ~ step ~ ~ ~").distance(6).gain(.1)

setcpm(132/4)

// An intro, two choruses, a piano break, one more chorus, and a coda
song("intro@4 (chorus@12)*2 break@12 chorus@12 coda@2", "once")
tempomap("0:33 52:33 54:22")

// Left-hand boogie figures for G, C and D
const lg = note("g1 b1 d2 e2 f2 e2 d2 b1")
const lc = note("c2 e2 g2 a2 bb2 a2 g2 e2")
const ld = note("d2 f#2 a2 b2 c3 b2 a2 f#2")
// Right-hand chords
const rg = note("[b4,d5,f5,g5]")
const rc = note("[bb4,c5,e5,g5]")
const rd = note("[a4,c5,d5,f#5]")

// Twelve bars, eight to the bar
left: stack(
  cat(ld, lc, lg, ld).sections("intro"),
  cat(lg, lg, lg, lg, lc, lc, lg, lg, ld, lc, lg, ld).sections("chorus break"),
  note("<[g1 b1 d2 e2 f2 e2 d2 b1] [g1@4 ~@4]>").sections("coda")
).swing(4)
  .s("triangle").timbre("bright").decay(.25).sustain(.2).lpf(1800).gain(.35)
right: stack(
  cat(rd, rc, rg, rd).struct("x [~@2 x] ~ [~@2 x]").sections("intro"),
  cat(rg, rg, rg, rg, rc, rc, rg, rg, rd, rc, rg, rd).struct("x [~@2 x] ~ [~@2 x]").sections("chorus"),
  cat(rg, rg, rg, rg, rc, rc, rg, rg, rd, rc, rg, rd).struct("[~ x x]*4").sections("break"),
  note("<[~ ~ ~ [b4,d5,g5]] [[g4,b4,d5,g5]@2 ~@2]>").sections("coda")
).s("triangle").timbre("bright").decay(.2).sustain(.1).lpf(3000).gain(.2)

// Close-harmony voices on the off-beats
voices: note("<[b3,d4,g4] [b3,d4,g4] [b3,d4,g4] [b3,d4,g4] [c4,e4,g4] [c4,e4,g4] [b3,d4,g4] [b3,d4,g4] [a3,d4,f#4] [c4,e4,g4] [b3,d4,g4] [a3,d4,f#4]>")
  .struct("~ [x@2 x] ~ x").sections("chorus")
  .s("ooh").attack(.02).release(.3).room(.3).gain(.2)

// A shuffle beat; only the hats keep going through the intro and the break
drums: s("bd ~ bd ~, ~ sd ~ sd, [hh@2 hh]*4").gain(.45).sections("chorus")
hats: s("[hh@2 hh]*4").gain(.3).sections("intro break")

setcpm(72/4)

// An intro, two verses, the bridge, a last verse, and the tag
song("intro@2 (verse@8)*2 bridge@8 verse@8 tag@2", "once")
tempomap("0:18 34:18 36:12")

// Triplet piano: C, Am, F, G in the verse; F, F, C, C, D7, D7, G, G7 in the bridge
piano: stack(
  note("<[c4,e4,g4] [a3,c4,e4] [a3,c4,f4] [b3,d4,g4]>").sections("verse"),
  note("<[a3,c4,f4] [a3,c4,f4] [g3,c4,e4] [g3,c4,e4] [a3,c4,f#4] [a3,c4,f#4] [b3,d4,g4] [b3,d4,f4]>").sections("bridge")
).struct("[x x x]*4")
  .s("triangle").timbre("bright").decay(.15).sustain(.1).release(.1).lpf(2600).gain(.18)

// A walking bass
bass: stack(
  note("<[c2 e2 g2 e2] [a1 c2 e2 c2]>").sections("intro"),
  note("<[c2 e2 g2 e2] [a1 c2 e2 c2] [f1 a1 c2 a1] [g1 b1 d2 b1]>").sections("verse"),
  note("<[f1 a1 c2 a1] [f1 a1 c2 a1] [c2 e2 g2 e2] [c2 e2 g2 e2] [d2 f#2 a2 f#2] [d2 f#2 a2 f#2] [g1 b1 d2 b1] [g1 b1 d2 f2]>").sections("bridge"),
  note("<[c2 ~ ~ ~] [c1@2 ~@2]>").sections("tag")
).s("sine").shape(.15).decay(.3).sustain(.4).gain(.5)

// A backbeat with triplet hats
drums: stack(
  s("bd ~ bd ~").gain(.5),
  s("~ sd ~ sd").room(.2).gain(.45),
  s("[hh hh hh]*4").hpf(6000).gain(.2)
).exceptSections("intro tag")
finish: s("<[[bd,cr] ~ ~ ~] ~>").gain(.45).sections("tag")

// The group sings ooh, ooh-ooh
backing: stack(
  note("<[e3,g3,c4] [e3,a3,c4] [f3,a3,c4] [d3,g3,b3]>").struct("x@2 x x@3 x x").sections("intro verse"),
  note("<[f3,a3,c4] [f3,a3,c4] [e3,g3,c4] [e3,g3,c4] [f#3,a3,c4] [f#3,a3,c4] [d3,g3,b3] [d3,f3,b3]>").struct("x@2 x x@3 x x").sections("bridge"),
  note("[e3,g3,c4,e4]").slow(2).sections("tag")
).s("ooh").attack(.03).release(.3).room(.4).gain(.2)

// A honking tenor sax
sax: stack(
  note("<[g4@2 e4 g4 c5@4] [a4@2 c5 e5 c5@4] [a4@2 f4 a4 c5@2 a4@2] [b4@2 d5 b4 g4@4]>").sections("verse"),
  note("<[c5@2 a4 c5 f5@4] [e5@2 d5 c5 a4@4] [g4@2 c5 e5 g5@4] [e5@2 d5 c5 g4@4] [a4@2 c5 d5 f#5@4] [e5@2 d5 c5 a4@4] [b4@2 d5 g5 f5@2 d5@2] [b4@4 d5@4]>").sections("bridge"),
  note("<[e5 d5 c5 a4 g4@4] [c5@4 ~@4]>").sections("tag")
).s("sawtooth").timbre("reed").vowel("o").lpf(2200).vib(5).vibdepth(.15)
  .attack(.02).sustain(.6).release(.15).pan(.6).gain(.22)

// The last chord on the piano
ending: note("<[c3,e3,g3,a3,e4] ~>").sections("tag")
  .s("triangle").timbre("bright").decay(1).sustain(.2).release(.8).lpf(2600).gain(.22)

setcpm(90/4)

// A muffled intro, verse and hook twice, a last verse, and the record stops
song("intro@4 (verse@8 hook@4)*2 verse@8 outro@4", "once")
tempomap("0:22.5 38:22.5 40:6")

// Dusty, swung drums that drop out for the last two beats of every section
drums: stack(
  s("bd ~ ~ bd ~ ~ bd ~, ~ ~ sd ~ ~ ~ sd ~").swing(4).crush(10).lpf(4500).gain(.75),
  s("hh*8").swing(4).hpf(6000).gain("[.3 .15]*4")
).exceptSections("intro outro")
  .atEnd(1, x => x.mask("1 0"))

// A jazz loop off an old record: Dm7, Dm7, Gm7, A7, muffled in the intro and outro
loop: note("<[d3,f3,a3,c4] [d3,f3,a3,c4] [g3,bb3,d4,f4] [a3,c#4,e4,g4]>").struct("x ~ ~ x ~ x ~ ~").swing(4)
  .s("sine").fm(1.1).fmh(2).trem(5).tremdepth(.2).crush(7)
  .lpf(bysec("intro:700 outro:700 *:1800")).decay(.6).sustain(.3).release(.4).gain(.3)

// An upright bass
bass: note("<[d2 ~ ~ d2 ~ ~ a1 c2] [d2 ~ ~ d2 ~ f2 e2 c2] [g1 ~ ~ g1 ~ ~ f1 g1] [a1 ~ ~ a1 ~ c#2 e2 a1]>").swing(4)
  .exceptSections("intro outro")
  .s("sine").shape(.1).decay(.4).sustain(.3).release(.1).gain(.55)

// A horn sample on the turnaround, and a busier one on the hook
horns: stack(
  note("<~ ~ ~ [~ ~ ~ ~ [c#5,e5] ~ [e5,g5] ~]>").sections("verse"),
  note("<[[d5,f5]@2 ~ [d5,f5] ~ ~ [c5,e5] ~] [~ ~ ~ ~ [d5,f5] ~ ~ ~] [[bb4,d5]@2 ~ [bb4,d5] ~ ~ [a4,c5] ~] [~ ~ ~ ~ [c#5,e5] ~ [e5,g5] ~]>").sections("hook")
).s("sawtooth").timbre("reed").crush(8).lpf(2000).decay(.2).sustain(.3).room(.3).gain(.18)

// Vinyl crackle
crackle: s("click*16?0.3").hpf(3000).gain(rand.range(.03, .1))
